def polyTensorEval {p : ℕ+} {l n d : ℕ} (C : PolyTensor p l n d)
    (x : Fin l → ZMod (p : ℕ)) : Fin n → ZMod (p : ℕ) :=
  fun j => ∑ tau : Fin d → Fin (l + 1), C j tau * ∏ i : Fin d, xhat x (tau i)

def encodeTensorBits {p : ℕ+} {l n d : ℕ} (width : ℕ) (C : PolyTensor p l n d) :
    Fin (n * (l + 1) ^ d * width) → Bool :=
  fun i => (encodeTensor width C).getD i.val false

def phfeEval {p : ℕ+} {l n d : ℕ} (C : PolyTensor p l (n * n) d)
    (x : Fin l → ZMod (p : ℕ)) (y : Fin n → ZMod (p : ℕ)) : ZMod (p : ℕ) :=
  quadEval C x y y

def phfeClassValueEquiv (l n w : PolyExpr) (d kappa : ℕ) (p : ℕ+) :
    (phfeClass l n w d).Out kappa ((phfeClassParamEquiv l n w d kappa).symm p) ≃
      ZMod (p : ℕ) := Equiv.refl _

def quadClassValueEquiv (l n1 n2 w : PolyExpr) (d kappa : ℕ) (p : ℕ+) :
    (quadClass l n1 n2 w d).Out kappa ((quadClassParamEquiv l n1 n2 w d kappa).symm p) ≃
      ZMod (p : ℕ) := Equiv.refl _

def Correct : Prop :=
  ∀ κ f x y, (S.honestRun κ f x y).AllOutputs fun o =>
    S.dec κ o.pp o.sk x o.ct = some (S.embed κ o.pp (C.eval κ (S.cprm κ o.pp) f x y))

def publicTensor (x : Fin l → ZMod (p : ℕ)) : Matrix (Fin l × M) M (ZMod (p : ℕ)) :=
  fun iu v => Matrix.kroneckerMap (fun a b => a * b)
    (fun i (_ : Fin 1) => x i) (1 : Matrix M M (ZMod (p : ℕ))) iu (0, v)

def matrix (C : PolyTensor p l n d) (x : Fin l → ZMod (p : ℕ)) :
    Matrix (TIdx l d ⊕ Fin n) (MIdx l d) (ZMod (p : ℕ)) :=
  L1 C * PartialGarbling.publicTensor x + L0 C

def rec (C : PolyTensor p l n d) (x : Fin l → ZMod (p : ℕ)) :
    (Fin n ⊕ MIdx l d) → ZMod (p : ℕ) :=
  Sum.elim (polyTensorEval C x) (forward x)

def shift (C : PolyTensor p l n d) (x : Fin l → ZMod (p : ℕ))
    (z : Fin n → ZMod (p : ℕ)) : (TIdx l d ⊕ Fin n) → ZMod (p : ℕ) :=
  Sum.elim (fun v => backward C x z (node v)) z

TCSlib.Cryptography.AdvancedEncryption.F.prose:
 A bounded next-move computation with deterministic stateful answers returns its output and
final state. A query with no remaining budget returns `timeout` and leaves the state unchanged;
an allowed query appends its query and answer to the history. Technical glue.

