def saChallengeQuery (kappa : ℕ) (x : Fin (C.pubLen.eval kappa) → Bool)
    (y : Fin (C.privLen.eval kappa) → Bool) : (S.saSpec kappa).dom 0 :=
  Fin.append x y

def saChallengeMove (kappa : ℕ) (x : Fin (C.pubLen.eval kappa) → Bool)
    (y : Fin (C.privLen.eval kappa) → Bool) : Move (S.saSpec kappa) Bool :=
  .query 0 (S.saChallengeQuery kappa x y)

def saCTAnswer (kappa : ℕ) (pp : PublicParams S.G kappa) (ct : Option (S.CT kappa pp)) :
    (S.saSpec kappa).rng 0 :=
  TCSlib.Cryptography.Composability.FixedLengthScheme.decAnswer (ct.map (S.encCT kappa pp))

def saSKAnswer (kappa : ℕ) (pp : PublicParams S.G kappa) (sk : Option (S.SK kappa pp)) :
    (S.saSpec kappa).rng 1 :=
  TCSlib.Cryptography.Composability.FixedLengthScheme.decAnswer (sk.map (S.encSK kappa pp))

def run (kappa : ℕ) (pp : PublicParams S.G kappa) (pk : S.MPK kappa pp) (r : List Bool) :
    OracleComp (S.saSpec kappa) Bool :=
  buildComp (A.next kappa pp pk r) false (A.budget.eval kappa) []

def saCommitment (A : TwoStage) (C : FnClass) (q : PolyExpr) (kappa : ℕ)
    (r : List Bool) : Commitment C q kappa :=
  Commitment.decode C q kappa (A.first.runAt kappa [] (A.firstCoins kappa r))

def SubexpSASimSecureWith (Sim : SASimulator.Raw S) : Prop :=
  ∃ c : ℝ, 0 < c ∧ ∀ A : NUPPT, ∀ q : PolyExpr,
    SubexpSmall c (S.saSimAdv Sim (toSAAdv (S := S) A q))

def encInputWord (kappa : ℕ) (pi : Sim.EncInput kappa) : List Bool :=
  pairEncode pi.pp.encode (pairEncode (Sim.encSt kappa pi.pp pi.state)
    (List.ofFn pi.publicInput))

abbrev KeyPack (G : BilinearGen) {ℓ n' : PolyExpr} {Fn : ℕ → ℕ+ → Type}
    (PG : PartialGarbling.Raw ℓ n' Fn) (κ : ℕ) (pp : PublicParams G κ) :=
  Σ f : Fn κ pp.orderParam, Key G PG κ pp f

theorem keyPack_eq (G : BilinearGen) {ℓ n' : PolyExpr} {Fn : ℕ → ℕ+ → Type}
    (PG : PartialGarbling.Raw ℓ n' Fn) (κ : ℕ) (pp : PublicParams G κ) :
    KeyPack G PG κ pp = (Σ f : Fn κ pp.orderParam, Key G PG κ pp f)

theorem saSpec_eq (G : BilinearGen) {ℓ n' : PolyExpr} {Fn : ℕ → ℕ+ → Type}
    (PG : PartialGarbling.Raw ℓ n' Fn) (zDim : PolyExpr) (κ : ℕ) (pp : PublicParams G κ) :
    saSpec G PG zDim κ pp =
      { dom := fun | false => Challenge G ℓ zDim κ pp | true => KeyQuery G PG zDim κ pp
        rng := fun | false => Option (CT G zDim κ pp) | true => Option (KeyPack G PG κ pp) }

abbrev SecurityDraw (G : BilinearGen) {ℓ n' : PolyExpr} {Fn : ℕ → ℕ+ → Type}
    (PG : PartialGarbling.Raw ℓ n' Fn) (zDim q : PolyExpr) (κ : ℕ) (pp : PublicParams G κ) :=
  Fin ((securityCount PG zDim q).eval κ) → ZMod pp.group.order

noncomputable def saSimAdv (G : BilinearGen) {ℓ n' : PolyExpr} {Fn : ℕ → ℕ+ → Type}
    (PG : PartialGarbling.Raw ℓ n' Fn) (zDim : PolyExpr) (A : SAAdv G PG zDim) (κ : ℕ) : ℝ :=
  advantage (saGame G PG zDim A false κ) (saGame G PG zDim A true κ)

def decomposedKey (G : BilinearGen) {ℓ n' : PolyExpr} {Fn : ℕ → ℕ+ → Type}
    (PG : PartialGarbling.Raw ℓ n' Fn) (zDim : PolyExpr) (κ : ℕ) (pp : PublicParams G κ)
    (st : SimState G ℓ zDim κ pp) (query : KeyQuery G PG zDim κ pp)
    (ω : KeyDraw G PG κ pp query.fn) : Key G PG κ pp query.fn :=
  let sk := keyCore G PG zDim κ pp ⟨st.W, st.U, st.V⟩ query.fn query.matrix ω
  let C := fun i j => st.basisInv i (Fin.castSucc j)
  let a := fun i => st.basisInv i (Fin.last 2)
  ⟨combineRows G κ pp C a (matMulGroup st.Aᵀ sk.K1) (groupVecMul st.c sk.K1),
    combineRows G κ pp C a (matMulGroup st.Aᵀ sk.K2) (groupVecMul st.c sk.K2),
    combineRows G κ pp C a (matMulGroup st.Aᵀ sk.K3) (groupVecMul st.c sk.K3), sk.R⟩

abbrev Advice {ℓ n' : PolyExpr} {Fn : ℕ → ℕ+ → Type}
    (PG : PartialGarbling.Raw ℓ n' Fn) (zDim q : PolyExpr) (p : ℕ → ℕ) (κ : ℕ) :=
  Fin ((securityCount PG zDim q).eval κ) → ZMod (p κ)

theorem advice_eq {ℓ n' : PolyExpr} {Fn : ℕ → ℕ+ → Type}
    (PG : PartialGarbling.Raw ℓ n' Fn) (zDim q : PolyExpr) (p : ℕ → ℕ) (κ : ℕ) :
    Advice PG zDim q p κ = (Fin ((securityCount PG zDim q).eval κ) → ZMod (p κ))

theorem advice_nonempty {ℓ n' : PolyExpr} {Fn : ℕ → ℕ+ → Type}
    (PG : PartialGarbling.Raw ℓ n' Fn) (zDim q : PolyExpr) (p : ℕ → ℕ) (κ : ℕ) :
    Nonempty (Advice PG zDim q p κ)

theorem advice_finite (G : BilinearGen) {ℓ n' : PolyExpr} {Fn : ℕ → ℕ+ → Type}
    (PG : PartialGarbling.Raw ℓ n' Fn) (zDim q : PolyExpr) (p : ℕ → ℕ)
    (hp : ∀ κ r, (G.inst κ r).order = p κ) (κ : ℕ) : Finite (Advice PG zDim q p κ)

def publicFromGroupA (G : BilinearGen) (ℓ zDim : PolyExpr) (κ : ℕ) (pp : PublicParams G κ)
    (A : Matrix (Fin 2) (Fin 3) pp.group.G) (st : MSK G ℓ zDim κ pp) : MPK G ℓ zDim κ pp :=
  ⟨A, groupMatMul A st.W, groupMatMul A st.U, groupMatMul A st.V⟩

noncomputable def red1 (G : BilinearGen) {ℓ n' : PolyExpr} {Fn : ℕ → ℕ+ → Type}
    (PG : PartialGarbling.Raw ℓ n' Fn) (zDim : PolyExpr) (p : ℕ → ℕ)
    (hp : ∀ κ r, (G.inst κ r).order = p κ) (A : SAAdv G PG zDim)
    (ω : ∀ κ, Advice PG zDim A.budget p κ) (κ : ℕ)
    (c : G.MDDHChallenge ℓ (PG.mBound.mul A.budget) κ) (r : List Bool) : List Bool :=
  let tape := adviceDraw G PG zDim A.budget p hp κ c.pp (ω κ)
  let ctx := simSetupCore G ℓ zDim κ c.pp (setupAt G PG zDim A.budget κ c.pp tape)
  if (basisMatrix G κ c.pp ctx.2.A ctx.2.c).det = 0 then [false]
  else [(runDet (A.next κ c.pp ctx.1 r) false
    (red1Handler G PG zDim A.budget κ c ctx.2 tape) (A.budget.eval κ) [] ⟨none, 0⟩).1]

theorem game0_real_accept (G : BilinearGen) {ℓ n' : PolyExpr} {Fn : ℕ → ℕ+ → Type}
    (PG : PartialGarbling.Raw ℓ n' Fn) (zDim : PolyExpr) (A : SAAdv G PG zDim) (κ : ℕ) :
    accept (game G PG zDim A 0 κ) = accept (saGame G PG zDim A false κ)

theorem game2_game3_accept (G : BilinearGen) {ℓ n' : PolyExpr} {Fn : ℕ → ℕ+ → Type}
    (PG : PartialGarbling.Raw ℓ n' Fn) (zDim : PolyExpr) (A : SAAdv G PG zDim) (κ : ℕ) :
    accept (game G PG zDim A 2 κ) = accept (game G PG zDim A 3 κ)

theorem game4_game5_accept (G : BilinearGen) {ℓ n' : PolyExpr} {Fn : ℕ → ℕ+ → Type}
    (PG : PartialGarbling.Raw ℓ n' Fn) (zDim : PolyExpr) (A : SAAdv G PG zDim) (κ : ℕ) :
    accept (game G PG zDim A 4 κ) = accept (game G PG zDim A 5 κ)

def simEnc (G : BilinearGen) (ℓ zDim : PolyExpr) (κ : ℕ) (pp : PublicParams G κ)
    (st : SimState G ℓ zDim κ pp) (x : Fin (ℓ.eval κ) → ZMod pp.group.order) :
    ProbComp (CT G zDim κ pp) := .pure (simEncCore G ℓ zDim κ pp st x)

def PGSound {ℓ n : PolyExpr} {d : ℕ}
    (PG : PartialGarbling.Raw ℓ (n.mul n) (TensorFn ℓ n d)) : Prop :=
  ∀ κ p f x, PG.eval κ p f x = polyTensorEval f x

theorem pgSound_iff {ℓ n : PolyExpr} {d : ℕ}
    (PG : PartialGarbling.Raw ℓ (n.mul n) (TensorFn ℓ n d)) :
    PGSound PG ↔ ∀ κ p f x, PG.eval κ p f x = polyTensorEval f x

def classParam (G : BilinearGen) (ℓ n : PolyExpr) (d κ : ℕ) (pp : PublicParams G κ) :
    (phfeClass ℓ n G.wG d).Prm κ :=
  (phfeClassParamEquiv ℓ n G.wG d κ).symm pp.orderParam

def valueEquiv (G : BilinearGen) (ℓ n : PolyExpr) (d κ : ℕ) (pp : PublicParams G κ) :
    (phfeClass ℓ n G.wG d).Out κ (classParam G ℓ n d κ pp) ≃ ZMod pp.group.order :=
  phfeClassValueEquiv ℓ n G.wG d κ pp.orderParam

def encMPK (G : BilinearGen) (ℓ n : PolyExpr) (κ : ℕ) (pp : PublicParams G κ)
    (pk : Quadratic.MPK G ℓ n n κ pp) : Fin ((mpkLen G ℓ n).eval κ) → Bool :=
  padFin ((mpkLen G ℓ n).eval κ) (Wire.quadraticMPK pp pk)

def encMSK (G : BilinearGen) (ℓ n : PolyExpr) (κ : ℕ) (pp : PublicParams G κ)
    (sk : Quadratic.MSK G ℓ n n κ pp) : Fin ((mskLen G ℓ n).eval κ) → Bool :=
  padFin ((mskLen G ℓ n).eval κ) (Wire.quadraticMSK pp sk)

def encCT (G : BilinearGen) (n : PolyExpr) (κ : ℕ) (pp : PublicParams G κ)
    (ct : Quadratic.CT G n n κ pp) : Fin ((ctLen G n).eval κ) → Bool :=
  padFin ((ctLen G n).eval κ) (Wire.quadraticCT pp ct)

theorem encSK_injective (G : BilinearGen) {ℓ n : PolyExpr} {d : ℕ}
    (PG : PartialGarbling.Raw ℓ (n.mul n) (TensorFn ℓ n d)) (κ : ℕ)
    (pp : PublicParams G κ) : Function.Injective (encSK G PG κ pp)

def publicParamsEquiv (G : BilinearGen) (ℓ n : PolyExpr) (d : ℕ)
    (PG : PartialGarbling.Raw ℓ (n.mul n) (TensorFn ℓ n d)) (κ : ℕ) :
    PublicParams (wee20PHFE_raw G ℓ n d PG).G κ ≃ PublicParams G κ := Equiv.refl _

def mpkLen (G : BilinearGen) (ℓ n : PolyExpr) : PolyExpr :=
  (((PolyExpr.const 16).add ((PolyExpr.const 24).mul n)).add ((PolyExpr.const 8).mul ℓ)).mul G.wG
    |>.add (PolyExpr.const 10)

def mskLen (G : BilinearGen) (ℓ n : PolyExpr) : PolyExpr :=
  (((((PolyExpr.const 8).mul (n.pow 3)).add ((PolyExpr.const 24).mul n)).add
    ((PolyExpr.const 12).mul ℓ)).add (PolyExpr.const 6)).mul G.wG |>.add (PolyExpr.const 6)

def signalCoord (n1 n2 : ℕ) :
    ((Fin 2 × Fin n2) ⊕ (Fin n1 × Fin 2)) ≃ Fin (2 * n2 + n1 * 2) :=
  (Equiv.sumCongr finProdFinEquiv finProdFinEquiv).trans finSumFinEquiv

abbrev Advice {ℓ : PolyExpr} (n1 n2 q : PolyExpr) {Fn : ℕ → ℕ+ → Type}
    (PG : PartialGarbling.Raw ℓ (n1.mul n2) Fn) (p : ℕ → ℕ) (κ : ℕ) :=
  MaskAdvice n1 n2 p κ × Linear.Advice PG (piDim n1 n2) q p κ

theorem advice_eq {ℓ : PolyExpr} (n1 n2 q : PolyExpr) {Fn : ℕ → ℕ+ → Type}
    (PG : PartialGarbling.Raw ℓ (n1.mul n2) Fn) (p : ℕ → ℕ) (κ : ℕ) :
    Advice n1 n2 q PG p κ = (MaskAdvice n1 n2 p κ × Linear.Advice PG (piDim n1 n2) q p κ)

theorem advice_nonempty {ℓ : PolyExpr} (n1 n2 q : PolyExpr) {Fn : ℕ → ℕ+ → Type}
    (PG : PartialGarbling.Raw ℓ (n1.mul n2) Fn) (p : ℕ → ℕ) (κ : ℕ) :
    Nonempty (Advice n1 n2 q PG p κ)

def maskAdviceMeta (n1 n2 : PolyExpr) (κ : ℕ) : List Bool :=
  let num := fun n => Candidates.natToList (Nat.size n) n
  pairEncode (List.replicate κ true) (pairEncode (num (n1.eval κ)) (num (n2.eval κ)))

def maskAdviceLen (G : BilinearGen) (n1 n2 : PolyExpr) : PolyExpr :=
  ((((PolyExpr.const 4).mul PolyExpr.var).add ((PolyExpr.const 4).mul n1)).add
    (((PolyExpr.const 2).mul n2).add (PolyExpr.const 20))).add ((maskCount n1 n2).mul G.wG)

def maskAt (G : BilinearGen) (n1 n2 : PolyExpr) (κ : ℕ) (pp : PublicParams G κ)
    (ω : MaskDraw G n1 n2 κ pp) (i : ℕ) : ZMod pp.group.order :=
  if h : i < (maskCount n1 n2).eval κ then ω ⟨i, h⟩ else 0

def maskedVectors (G : BilinearGen) (ℓ n1 n2 : PolyExpr) (mode : Fin 5)
    (κ : ℕ) (pp : PublicParams G κ) (m : Masks G n1 n2 κ pp)
    (msg : Challenge G ℓ n1 n2 κ pp) :
    (Fin (n1.eval κ) → ZMod pp.group.order) × (Fin (n2.eval κ) → ZMod pp.group.order) :=
  (if 3 ≤ mode.val then m.y1 else Matrix.vecMul m.s1 m.A1 + msg.2.1,
    if 4 ≤ mode.val then m.y2 else Matrix.vecMul m.s2 m.A2 + msg.2.2)

def quadraticMPK {ℓ n1 n2 : PolyExpr} (pk : Quadratic.MPK G ℓ n1 n2 κ pp) : List Bool :=
  pairEncode (groupMatrix pp pk.A1)
    (pairEncode (groupMatrix pp pk.A2) (linearMPK pp pk.linear))

def quadraticKey {n1 n2 : PolyExpr} {Fn : ℕ → ℕ+ → Type}
    (PG : PartialGarbling.Raw ℓ (n1.mul n2) Fn) {f : Fn κ pp.orderParam}
    (sk : Quadratic.Key G n1 n2 PG κ pp f) : List Bool :=
  pairEncode (groupMatrix pp sk.matrix) (linearKey pp PG sk.linear)

theorem quadraticKey_eq {n1 n2 : PolyExpr} {Fn : ℕ → ℕ+ → Type}
    (PG : PartialGarbling.Raw ℓ (n1.mul n2) Fn) {f : Fn κ pp.orderParam}
    (sk : Quadratic.Key G n1 n2 PG κ pp f) :
    quadraticKey pp PG sk = pairEncode (groupMatrix pp sk.matrix)
      (linearKey pp PG sk.linear)

def quadraticEncDraw (ω : Quadratic.EncDraw G κ pp) : List Bool :=
  [scalarVector pp ω.1, scalarVector pp ω.2.1,
    scalarVector pp ω.2.2].foldr pairEncode []

def linearKeyDraw {ℓ n' : PolyExpr} {Fn : ℕ → ℕ+ → Type}
    (PG : PartialGarbling.Raw ℓ n' Fn) {f : Fn κ pp.orderParam}
    (ω : Linear.KeyDraw G PG κ pp f) : List Bool :=
  [scalarMatrix pp (fun i j => ω.1 i ((PG.rowCoord κ pp.orderParam f).symm j)),
    scalarMatrix pp (fun i j => ω.2 i ((PG.mCoord κ pp.orderParam f).symm j))].foldr
    pairEncode []

